use split_decls_genesis :: ourprelude :: * ; use rustc_data_structures :: fx :: FxIndexMap ; use rustc_data_structures :: graph :: scc :: Sccs ; use rustc_data_structures :: graph :: vec_graph :: VecGraph ; use rustc_index :: Idx ; use rustc_middle :: span_bug ; use rustc_middle :: ty :: error :: TypeError ; use tracing :: { debug , instrument } ; use super :: * ; use crate :: infer :: relate :: RelateResult ; use crate :: infer :: snapshot :: CombinedSnapshot ; impl < 'tcx > RegionConstraintCollector < '_ , 'tcx > { #[doc = " Searches new universes created during `snapshot`, looking for"] #[doc = " placeholders that may \"leak\" out from the universes they are contained"] #[doc = " in. If any leaking placeholders are found, then an `Err` is returned"] #[doc = " (typically leading to the snapshot being reversed). This algorithm"] #[doc = " only looks at placeholders which cannot be named by `outer_universe`,"] #[doc = " as this is the universe we're currently checking for a leak."] #[doc = ""] #[doc = " The leak check *used* to be the only way we had to handle higher-ranked"] #[doc = " obligations. Now that we have integrated universes into the region"] #[doc = " solvers, this is no longer the case, but we retain the leak check for"] #[doc = " backwards compatibility purposes. In particular, it lets us make \"early\""] #[doc = " decisions about whether a region error will be reported that are used in"] #[doc = " coherence and elsewhere -- see #56105 and #59490 for more details. The"] #[doc = " eventual fate of the leak checker is not yet settled."] #[doc = ""] #[doc = " The leak checker works by searching for the following error patterns:"] #[doc = ""] #[doc = " * P1: P2, where P1 != P2"] #[doc = " * P1: R, where R is in some universe that cannot name P1"] #[doc = ""] #[doc = " The idea here is that each of these patterns represents something that"] #[doc = " the region solver would eventually report as an error, so we can detect"] #[doc = " the error early. There is a fly in the ointment, though, in that this is"] #[doc = " not entirely true. In particular, in the future, we may extend the"] #[doc = " environment with implied bounds or other info about how placeholders"] #[doc = " relate to regions in outer universes. In that case, `P1: R` for example"] #[doc = " might become solvable."] #[doc = ""] #[doc = " # Summary of the implementation"] #[doc = ""] #[doc = " The leak checks as follows. First, we construct a graph where `R2: R1`"] #[doc = " implies `R2 -> R1`, and we compute the SCCs."] #[doc = ""] #[doc = " For each SCC S, we compute:"] #[doc = ""] #[doc = " * what placeholder P it must be equal to, if any"] #[doc = "   * if there are multiple placeholders that must be equal, report an error because `P1: P2`"] #[doc = " * the minimum universe of its constituents"] #[doc = ""] #[doc = " Then we walk the SCCs in dependency order and compute"] #[doc = ""] #[doc = " * what placeholder they must outlive transitively"] #[doc = "   * if they must also be equal to a placeholder, report an error because `P1: P2`"] #[doc = " * minimum universe U of all SCCs they must outlive"] #[doc = "   * if they must also be equal to a placeholder P, and U cannot name P, report an error, as"] #[doc = "     that indicates `P: R` and `R` is in an incompatible universe"] #[doc = ""] #[doc = " To improve performance and for the old trait solver caching to be sound, this takes"] #[doc = " an optional snapshot in which case we only look at region constraints added in that"] #[doc = " snapshot. If we were to not do that the `leak_check` during evaluation can rely on"] #[doc = " region constraints added outside of that evaluation. As that is not reflected in the"] #[doc = " cache key this would be unsound."] #[doc = ""] #[doc = " # Historical note"] #[doc = ""] #[doc = " Older variants of the leak check used to report errors for these"] #[doc = " patterns, but we no longer do:"] #[doc = ""] #[doc = " * R: P1, even if R cannot name P1, because R = 'static is a valid sol'n"] #[doc = " * R: P1, R: P2, as above"] #[instrument (level = "debug" , skip (self , tcx , only_consider_snapshot) , ret)] pub fn leak_check (self , tcx : TyCtxt < 'tcx > , outer_universe : ty :: UniverseIndex , max_universe : ty :: UniverseIndex , only_consider_snapshot : Option < & CombinedSnapshot < 'tcx > > ,) -> RelateResult < 'tcx , () > { if outer_universe == max_universe { return Ok (()) ; } let mini_graph = MiniGraph :: new (& self , only_consider_snapshot) ; let mut leak_check = LeakCheck :: new (tcx , outer_universe , max_universe , mini_graph , self) ; leak_check . assign_placeholder_values () ? ; leak_check . propagate_scc_value () ? ; Ok (()) } } struct LeakCheck < 'a , 'tcx > { tcx : TyCtxt < 'tcx > , outer_universe : ty :: UniverseIndex , mini_graph : MiniGraph < 'tcx > , rcc : RegionConstraintCollector < 'a , 'tcx > , scc_placeholders : IndexVec < LeakCheckScc , Option < ty :: PlaceholderRegion > > , scc_universes : IndexVec < LeakCheckScc , SccUniverse < 'tcx > > , } impl < 'a , 'tcx > LeakCheck < 'a , 'tcx > { fn new (tcx : TyCtxt < 'tcx > , outer_universe : ty :: UniverseIndex , max_universe : ty :: UniverseIndex , mini_graph : MiniGraph < 'tcx > , rcc : RegionConstraintCollector < 'a , 'tcx > ,) -> Self { let dummy_scc_universe = SccUniverse { universe : max_universe , region : None } ; let num_sccs = mini_graph . sccs . num_sccs () ; Self { tcx , outer_universe , mini_graph , rcc , scc_placeholders : IndexVec :: from_elem_n (None , num_sccs) , scc_universes : IndexVec :: from_elem_n (dummy_scc_universe , num_sccs) , } } #[doc = " Compute what placeholders (if any) each SCC must be equal to."] #[doc = " Also compute the minimum universe of all the regions in each SCC."] fn assign_placeholder_values (& mut self) -> RelateResult < 'tcx , () > { for (region , leak_check_node) in & self . mini_graph . nodes { let scc = self . mini_graph . sccs . scc (* leak_check_node) ; let universe = self . rcc . universe (* region) ; debug ! ("assign_placeholder_values: scc={:?} universe={:?} region={:?}" , scc , universe , region) ; self . scc_universes [scc] . take_min (universe , * region) ; if let ty :: RePlaceholder (placeholder) = region . kind () { if self . outer_universe . cannot_name (placeholder . universe) { match self . scc_placeholders [scc] { Some (p) => { assert_ne ! (p , placeholder) ; return Err (self . placeholder_error (p , placeholder)) ; } None => { self . scc_placeholders [scc] = Some (placeholder) ; } } } } } Ok (()) } #[doc = " For each SCC S, iterate over each successor S1 where `S: S1`:"] #[doc = ""] #[doc = " * Compute"] #[doc = " Iterate over each SCC `S` and ensure that, for each `S1` where `S1: S`,"] #[doc = " `universe(S) <= universe(S1)`. This executes after"] #[doc = " `assign_placeholder_values`, so `universe(S)` is already the minimum"] #[doc = " universe of any of its direct constituents."] fn propagate_scc_value (& mut self) -> RelateResult < 'tcx , () > { for scc1 in self . mini_graph . sccs . all_sccs () { debug ! ("propagate_scc_value: scc={:?} with universe {:?}" , scc1 , self . scc_universes [scc1]) ; let mut scc1_universe = self . scc_universes [scc1] ; let mut succ_bound = None ; for & scc2 in self . mini_graph . sccs . successors (scc1) { let SccUniverse { universe : scc2_universe , region : scc2_region } = self . scc_universes [scc2] ; scc1_universe . take_min (scc2_universe , scc2_region . unwrap ()) ; if let Some (b) = self . scc_placeholders [scc2] { succ_bound = Some (b) ; } } self . scc_universes [scc1] = scc1_universe ; if let Some (scc1_placeholder) = self . scc_placeholders [scc1] { debug ! ("propagate_scc_value: scc1={:?} placeholder={:?} scc1_universe={:?}" , scc1 , scc1_placeholder , scc1_universe) ; if scc1_universe . universe . cannot_name (scc1_placeholder . universe) { return Err (self . error (scc1_placeholder , scc1_universe . region . unwrap ())) ; } if let Some (scc2_placeholder) = succ_bound { assert_ne ! (scc1_placeholder , scc2_placeholder) ; return Err (self . placeholder_error (scc1_placeholder , scc2_placeholder)) ; } } else { self . scc_placeholders [scc1] = succ_bound ; } } Ok (()) } fn placeholder_error (& self , placeholder1 : ty :: PlaceholderRegion , placeholder2 : ty :: PlaceholderRegion ,) -> TypeError < 'tcx > { self . error (placeholder1 , ty :: Region :: new_placeholder (self . tcx , placeholder2)) } fn error (& self , placeholder : ty :: PlaceholderRegion , other_region : ty :: Region < 'tcx > ,) -> TypeError < 'tcx > { debug ! ("error: placeholder={:?}, other_region={:?}" , placeholder , other_region) ; TypeError :: RegionsInsufficientlyPolymorphic (placeholder . bound , other_region) } } #[doc = " Tracks the \"minimum universe\" for each SCC, along with some region that"] #[doc = " caused it to change."] #[derive (Copy , Clone , Debug)] struct SccUniverse < 'tcx > { #[doc = " For some SCC S, the minimum universe of:"] #[doc = ""] #[doc = " * each region R in S"] #[doc = " * each SCC S1 such that S: S1"] universe : ty :: UniverseIndex , #[doc = " Some region that caused `universe` to be what it is."] region : Option < ty :: Region < 'tcx > > , } impl < 'tcx > SccUniverse < 'tcx > { #[doc = " If `universe` is less than our current universe, then update"] #[doc = " `self.universe` and `self.region`."] fn take_min (& mut self , universe : ty :: UniverseIndex , region : ty :: Region < 'tcx >) { if universe < self . universe || self . region . is_none () { self . universe = universe ; self . region = Some (region) ; } } } rustc_index :: newtype_index ! { #[orderable] #[debug_format = "LeakCheckNode({})"] struct LeakCheckNode { } } rustc_index :: newtype_index ! { #[orderable] #[debug_format = "LeakCheckScc({})"] struct LeakCheckScc { } } #[doc = " Represents the graph of constraints. For each `R1: R2` constraint we create"] #[doc = " an edge `R1 -> R2` in the graph."] struct MiniGraph < 'tcx > { #[doc = " Map from a region to the index of the node in the graph."] nodes : FxIndexMap < ty :: Region < 'tcx > , LeakCheckNode > , #[doc = " Map from node index to SCC, and stores the successors of each SCC. All"] #[doc = " the regions in the same SCC are equal to one another, and if `S1 -> S2`,"] #[doc = " then `S1: S2`."] sccs : Sccs < LeakCheckNode , LeakCheckScc > , } impl < 'tcx > MiniGraph < 'tcx > { fn new (region_constraints : & RegionConstraintCollector < '_ , 'tcx > , only_consider_snapshot : Option < & CombinedSnapshot < 'tcx > > ,) -> Self { let mut nodes = FxIndexMap :: default () ; let mut edges = Vec :: new () ; Self :: iterate_region_constraints (region_constraints , only_consider_snapshot , | target , source | { let source_node = Self :: add_node (& mut nodes , source) ; let target_node = Self :: add_node (& mut nodes , target) ; edges . push ((source_node , target_node)) ; } ,) ; let graph = VecGraph :: < _ , false > :: new (nodes . len () , edges) ; let sccs = Sccs :: new (& graph) ; Self { nodes , sccs } } #[doc = " Invokes `each_edge(R1, R2)` for each edge where `R2: R1`"] fn iterate_region_constraints (region_constraints : & RegionConstraintCollector < '_ , 'tcx > , only_consider_snapshot : Option < & CombinedSnapshot < 'tcx > > , mut each_edge : impl FnMut (ty :: Region < 'tcx > , ty :: Region < 'tcx >) ,) { if let Some (snapshot) = only_consider_snapshot { for undo_entry in region_constraints . undo_log . region_constraints_in_snapshot (& snapshot . undo_snapshot) { match undo_entry { & AddConstraint (i) => { let c = region_constraints . data () . constraints [i] . 0 ; each_edge (c . sub , c . sup) ; } & AddVerify (i) => span_bug ! (region_constraints . data () . verifys [i] . origin . span () , "we never add verifications while doing higher-ranked things" ,) , & AddCombination (..) | & AddVar (..) => { } } } } else { region_constraints . data () . constraints . iter () . for_each (| (c , _) | each_edge (c . sub , c . sup)) } } fn add_node (nodes : & mut FxIndexMap < ty :: Region < 'tcx > , LeakCheckNode > , r : ty :: Region < 'tcx > ,) -> LeakCheckNode { let l = nodes . len () ; * nodes . entry (r) . or_insert (LeakCheckNode :: new (l)) } }